// ========================================================
//  v0.32: «ПОДГОНКА» — как устроена Мастерская. Открывается при первом заходе туда целиком.
//  Цифры — из config.js (тиры, шансы, цены, бонусы), чтобы статья не врала после правок баланса.
//  rows — таблица под текстом куска: [[подпись, значение], …].
// ========================================================
LORE_ARTICLES.refine = (function () {
  const tiers = Object.keys(MAX_TIER_REFINE).map(Number).sort((a, b) => a - b);
  const top = Math.max(...tiers.map(t => MAX_TIER_REFINE[t]));
  const chanceRows = [];
  for (let from = 1; from <= top; from += REFINE_CHANCE_STEP) {
    chanceRows.push([`+${from}…+${Math.min(top, from + REFINE_CHANCE_STEP - 1)}`, `${getRefineChance(from - 1)}%`]);
  }
  const jt = Object.keys(JEWELRY_MILESTONE_BY_TIER).map(Number).sort((a, b) => a - b);
  const jv = key => jt.map(t => '+' + JEWELRY_MILESTONE_BY_TIER[t][key] + '%').join(' / ');
  return {
    cat: 'world', title: 'Подгонка', kind: 'Мастерская',
    parts: [
      { key: 'refine', text: 'В Мастерской надетую вещь подгоняют по руке. Каждая удачная подгонка поднимает её уровень на +1 и даёт бонус. Подогнанная вещь заметна по «+N» у названия.' },
      { key: 'refine.limit', label: 'Предел', text: 'Сколько раз можно подогнать вещь, зависит от её тира.',
        rows: tiers.map(t => [`Тир ${t}`, `до +${MAX_TIER_REFINE[t]}`]) },
      { key: 'refine.chance', label: 'Шанс', text: 'Чем выше подгонка, тем упрямее вещь. Первые пять подгонок удаются всегда.',
        rows: chanceRows },
      { key: 'refine.price', label: 'Цена', text: 'Попытка стоит Оболов — и при удаче, и при неудаче. Неудача уровень подгонки не снимает.',
        rows: tiers.map(t => [`Тир ${t}`, `${REFINE_PRICE_BY_TIER[t].toLocaleString('ru-RU')} Оболов`]) },
      { key: 'refine.bonus', label: 'Бонус подгонки', text: 'Обычная подгонка даёт один случайный бонус: HP, MP, реген HP или MP вне боя, +1 точности, +1 уворота, +1% опыта, владения, Оболов или дропа. Оружию и бижутерии может выпасть +0.5% крита, щиту — +1% блока. HP, MP и реген тем больше, чем выше тир вещи.',
        rows: tiers.map(t => { const v = getRefineFlatValues(t); return [`Тир ${t}`, `+${v.hp} HP · +${v.mp} MP · +${v.regen}/сек`]; }) },
      { key: 'refine.milestone', label: 'Вехи', text: 'Каждая пятая подгонка (+5, +10, +15…) — веха. Вместо случайного бонуса вещь получает свой, гарантированный. Вехи оружия и доспехов растут: на первой +1, на второй ещё +2, на третьей ещё +3.',
        rows: [
          ['Оружие', 'Атака +1, +2, +3… (посох — маг. атака)'],
          ['Щит и доспехи', 'Защита +1, +2, +3…'],
          ['Ожерелье', `Опыт ${jv('necklace')} за веху (тир ${jt.join(' / ')})`],
          ['Кольцо', `Мастерство ${jv('ring')} за веху`],
          ['Серьга', `Опыт ${jv('earringXp')} или мастерство ${jv('earringProf')} — что выпадет на первой вехе`],
        ] },
    ],
  };
})();

